WITH exploded AS (SELECT id, service, log_ts, level, latency_ms, status_code, k, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS k, attr_value), unpacked AS (SELECT service, status_code, k, CAST((status_code & 2) != 0 AS INT) AS is_flagged, SHIFTRIGHT(status_code, 2) AS status_code_high FROM exploded WHERE status_code <= 417), base AS (SELECT *, CAST(status_code_high AS DOUBLE) AS status_code_high_num, COALESCE(k, 'N/A') AS resolved_k FROM unpacked WHERE k IS NOT NULL AND service IN ('auth', 'search', 'checkout')), valid AS (SELECT service, status_code, is_flagged, status_code_high, status_code_high_num, resolved_k, status_code_high_num + status_code AS status_code_high_num_plus_status_code, COALESCE(k, 'OTHER') AS resolved_k_2 FROM base WHERE is_flagged < 0), base_app_logs AS (SELECT service, status_code_high, status_code_high_num, resolved_k, status_code_high_num_plus_status_code, resolved_k_2, CASE WHEN service = 'search' THEN 1 ELSE 0 END AS is_search, CAST(status_code_high_num AS INT) AS status_code_high_num_int FROM valid WHERE status_code_high IS NOT NULL) SELECT service, CASE WHEN status_code_high >= 3 THEN 'HIGH' ELSE 'LOW' END AS status_code_high_tier, CASE WHEN status_code_high_num >= 71 THEN 'PREMIUM' ELSE 'STANDARD' END AS status_code_high_num_tier, COUNT(*) FILTER (WHERE service = 'checkout') AS checkout_rows, COUNT(*) FILTER (WHERE service = 'billing') AS billing_rows, MAX(status_code_high_num) FILTER (WHERE service = 'checkout') AS checkout_max_status_code_high_num, COUNT(*) FILTER (WHERE service = 'search') AS search_rows, SORT_ARRAY(COLLECT_SET(service)) AS service_list FROM base_app_logs GROUP BY service, CASE WHEN status_code_high >= 3 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN status_code_high_num >= 71 THEN 'PREMIUM' ELSE 'STANDARD' END
